// ============================================
// ORDER PROCESSOR - обработка заказа
// ============================================

// Получаем данные (могут быть в body или напрямую)
let input = $input.first().json;

console.log('=== ВХОДНЫЕ ДАННЫЕ ===');
console.log(JSON.stringify(input, null, 2));

// Если данные в поле body (от API Gateway)
if (input.body) {
  input = input.body;
}

// Если данные в поле data
if (input.data) {
  input = input.data;
}

const startTime = Date.now();

// Извлекаем данные
const orderId = input.orderId || 'unknown';
const customerId = input.customerId || 'unknown';
const productId = input.productId || 'unknown';
const quantity = input.quantity || 0;
const total = input.total || 0;

console.log('🔄 Обработка заказа:', orderId);
console.log('👤 Клиент:', customerId);
console.log('📦 Товар:', productId);
console.log('🔢 Количество:', quantity);
console.log('💰 Сумма:', total);

// Имитация проверки склада
await new Promise(r => setTimeout(r, 500));

// Формирование счета
const invoiceId = 'inv_' + Date.now();

const result = {
  success: true,
  orderId: orderId,
  invoiceId: invoiceId,
  duration: Date.now() - startTime,
  status: 'completed',
  productId: productId,
  quantity: quantity,
  total: total,
  customerId: customerId
};

console.log('✅ Заказ ' + orderId + ' выполнен за ' + result.duration + 'ms');

return [{
  json: result
}];

// ============================================
// СОХРАНЕНИЕ РЕЗУЛЬТАТА В EVENT STORE
// ============================================

const data = $input.first().json;

const eventData = {
  eventId: 'evt_' + Date.now(),
  eventType: 'order.completed',
  timestamp: new Date().toISOString(),
  data: data,
  source: 'order-processor'
};

console.log('📤 Сохраняем результат в Event Store');
console.log('📦 Заказ:', data.orderId);
console.log('💰 Сумма:', data.total);

await $http.post('/webhook/event-store', {
  headers: { 'Content-Type': 'application/json' },
  body: eventData
});

console.log('✅ Результат сохранен');

return [data];

// ============================================
// ОТПРАВКА В NOTIFICATION
// ============================================

const data = $input.first().json;

console.log('📧 Отправляем уведомление для заказа:', data.orderId);

await $http.post('/webhook/notification', {
  headers: { 'Content-Type': 'application/json' },
  body: data
});

console.log('✅ Уведомление отправлено');

return [data];
